import { tags } from "typia";

/**
 * Configuration for user session behavior and security.
 *
 * Defines rules for session creation, expiration, renewal, and security within
 * the system.
 *
 * This policy controls how long users remain logged in, how sessions are
 * managed across devices, and what security measures are applied.
 *
 * Critical for maintaining secure user sessions throughout the application
 * lifetime.
 *
 * @autobe Generated by AutoBE - https://github.com/wrtnlabs/autobe
 */
export type IShoppingMallSecurityPoliciesSessionManagement = {
  /**
   * Maximum duration of a user session in minutes before automatic logout.
   *
   * Default value is 120 minutes (2 hours). Minimum is 1 minute to prevent
   * immediate timeouts, maximum is 4320 minutes (3 days) to balance security
   * and usability.
   *
   * Sessions are automatically invalidated after this time period regardless
   * of activity, enforcing regular re-authentication for security.
   *
   * This setting applies to all user types: customers, sellers, and
   * administrators.
   */
  sessionTimeoutMinutes: number &
    tags.Type<"int32"> &
    tags.Minimum<1> &
    tags.Maximum<4320>;

  /**
   * Maximum number of concurrent sessions allowed per user account.
   *
   * Allows users to remain logged in on multiple devices simultaneously, with
   * a practical upper limit.
   *
   * Minimum value is 1 to ensure basic functionality, maximum value is 10 to
   * prevent account sharing abuse and resource exhaustion.
   *
   * When limit is reached, the oldest session is automatically terminated
   * when a new login occurs.
   */
  maxConcurrentSessions: number &
    tags.Type<"int32"> &
    tags.Minimum<1> &
    tags.Maximum<10>;

  /**
   * Enforces two-factor authentication for all user sessions.
   *
   * When true, all users must complete two-factor authentication during login
   * and after extended periods of inactivity.
   *
   * When false, two-factor authentication is optional but recommended for
   * administrators and sellers.
   *
   * Enabling this significantly improves account security against credential
   * theft and phishing attacks.
   */
  require2FA: boolean;

  /**
   * Determines whether session timeout countdown resets on user activity.
   *
   * When true, every API request made by the user resets the session timer,
   * extending the session duration as long as activity continues.
   *
   * When false, the session timer runs independently of user activity,
   * expiring precisely at the configured sessionTimeoutMinutes.
   *
   * Enabling this improves user experience by preventing unexpected logouts
   * during active work.
   */
  renewSessionOnActivity: boolean;

  /**
   * Controls whether revoking a user's active sessions causes permanent
   * logout.
   *
   * When true, any administrative action that revokes sessions (e.g.,
   * password change, security audit) immediately terminates all active
   * sessions and requires full re-authentication.
   *
   * When false, session revocation only marks sessions for expiration at next
   * timeout, allowing pending operations to complete.
   *
   * This setting is critical for security-critical operations like password
   * resets and privileged access audits.
   */
  permanentLogoutOnRevoke: boolean;

  /**
   * Requires all session cookies to be transmitted over HTTPS only and marked
   * as HttpOnly and Secure.
   *
   * When true, session cookies cannot be transmitted over plaintext HTTP
   * connections and are inaccessible to client-side JavaScript.
   *
   * When false, cookies may be transmitted over HTTP (insecure) and
   * potentially accessible via XSS attacks.
   *
   * This is a mandatory security requirement for production environments and
   * should always be set to true.
   */
  enforceSecureCookie: boolean;

  /**
   * Sets the SameSite attribute for session cookies to control cross-site
   * request behavior.
   *
   * - Strict: Cookies are sent only in first-party contexts, preventing any
   *   cross-site requests.
   * - Lax: Cookies are sent with top-level navigations but not cross-site
   *   subrequests (recommended default).
   * - None: Cookies are sent with all requests, but requires Secure attribute
   *   to be true.
   *
   * Lax is appropriate for e-commerce systems where account navigation
   * between site entities is common, while maintaining CSRF protection.
   */
  cookieSameSite: "Strict" | "Lax" | "None";

  /**
   * Maximum duration of access tokens before they expire, in minutes.
   *
   * Access tokens are used for API authentication and must be refreshed
   * periodically for security.
   *
   * Minimum value is 5 minutes to ensure timely token refresh cycles, maximum
   * value is 1440 minutes (24 hours) to balance security and convenience.
   *
   * Shorter expiration times increase security but require more frequent
   * refresh operations.
   */
  tokenExpirationMinutes: number &
    tags.Type<"int32"> &
    tags.Minimum<5> &
    tags.Maximum<1440>;

  /**
   * Maximum lifetime of refresh tokens before they expire, in hours.
   *
   * Refresh tokens are used to obtain new access tokens without requiring
   * full login.
   *
   * Minimum value is 24 hours (1 day) to support reasonable session
   * persistence, maximum value is 168 hours (7 days) to limit exposure of
   * long-lived credentials.
   *
   * Refresh tokens must be stored securely on the client and revoked upon
   * logout or security events.
   */
  refreshTokenLifetimeHours: number &
    tags.Type<"int32"> &
    tags.Minimum<24> &
    tags.Maximum<168>;

  /**
   * Automatically revokes all active sessions when a user changes their
   * password.
   *
   * Ensures that devices where the old password was used are immediately
   * logged out after a password change.
   *
   * Critical for preventing ongoing access by unauthorized parties who may
   * have compromised credentials.
   *
   * Should always be set to true in production environments.
   */
  sessionRevokeOnPasswordChange: boolean;

  /**
   * Automatically revokes all active sessions when two-factor authentication
   * is enabled.
   *
   * When a user enables 2FA, it often indicates a security-conscious action
   * or potential credential compromise.
   *
   * Revoking sessions at this point ensures that any existing sessions made
   * with just the password (and without 2FA) are terminated, forcing
   * re-authentication with the new security layer.
   */
  sessionRevokeOn2FAEnable: boolean;

  /**
   * Maximum number of password reset attempts allowed within a short time
   * window.
   *
   * Used to prevent brute-force attacks on password reset functionality.
   *
   * After exceeding this limit, the user is temporarily locked out of the
   * password reset process.
   *
   * Minimum of 1 prevents abuse, maximum of 5 allows for reasonable user
   * errors.
   *
   * This is independent of login attempt limits and applies specifically to
   * password recovery flows.
   */
  maxPasswordResetAttempts: number &
    tags.Type<"int32"> &
    tags.Minimum<1> &
    tags.Maximum<5>;

  /**
   * Number of consecutive failed authentication attempts that trigger a
   * security alert.
   *
   * Used to detect potential brute force or credential stuffing attacks
   * before successful breaches occur.
   *
   * When threshold is exceeded, system administrators are alerted and the
   * affected account may be temporarily locked.
   *
   * Threshold of 1 triggers alerts immediately for any failure, while higher
   * values prevent alert fatigue from accidental mistakes.
   *
   * Value over 50 is discouraged as it reduces security effectiveness.
   */
  sessionSecurityAlertThreshold: number &
    tags.Type<"int32"> &
    tags.Minimum<1> &
    tags.Maximum<50>;

  /**
   * Enables automatic cleanup of expired and orphaned sessions from the
   * database.
   *
   * When true, background jobs regularly purge session records that have
   * exceeded their lifetime or whose associated users no longer exist.
   *
   * When false, all sessions are retained until manually cleaned, potentially
   * leading to database growth and performance degradation over time.
   *
   * Should always be enabled in production to maintain system efficiency and
   * reduce attack surface.
   */
  enableAutomaticSessionCleanup: boolean;

  /**
   * Prevents guest users (non-authenticated) from maintaining persistent
   * sessions.
   *
   * When true, guest users can browse but cannot maintain cart state or
   * preferences across sessions beyond the browser lifetime.
   *
   * When false, guest sessions are stored server-side and can persist for
   * some time (e.g., 30 days).
   *
   * This setting is primarily relevant for e-commerce behavior and should be
   * enabled for higher security compliance.
   */
  disableSessionPersistenceForGuests: boolean;

  /**
   * Override for session timeout specifically for administrator accounts.
   *
   * Administrators require longer sessions for complex maintenance tasks.
   *
   * Must be greater than the general sessionTimeoutMinutes (minimum 15
   * minutes) to ensure usability for administrative workflows.
   *
   * Maximum value is 720 minutes (12 hours) to balance administrative
   * efficiency with security requirements.
   *
   * If not set, general session timeout rules apply to admin accounts.
   */
  adminSessionTimeoutOverrideMinutes: number &
    tags.Type<"int32"> &
    tags.Minimum<15> &
    tags.Maximum<720>;

  /**
   * Enforces two-factor authentication requirement for all administrator
   * actions.
   *
   * When true, administrator sessions are treated as high-privilege and
   * require 2FA for every API request.
   *
   * When false, administrators follow the same 2FA rules as other users (if
   * enabled globally).
   *
   * Enabling this is mandatory for SOC2, ISO27001, and other enterprise
   * compliance standards.
   */
  adminSession2FAEnforcement: boolean;

  /**
   * Maximum number of concurrent sessions allowed for administrator accounts.
   *
   * Administrators are high-privilege users and should have limited
   * concurrent sessions to prevent credential abuse.
   *
   * Minimum value of 1 ensures basic functionality, maximum of 3 prevents
   * account sharing while allowing use on multiple devices.
   *
   * Typical values are 1 or 2 for strict security environments, 3 for liberal
   * environments requiring mobility.
   */
  maxAdminConcurrentSessions: number &
    tags.Type<"int32"> &
    tags.Minimum<1> &
    tags.Maximum<3>;

  /**
   * Enables detailed audit logging of all session-related events.
   *
   * When true, every session creation, renewal, revocation, timeout, and
   * security event is logged to the audit trail.
   *
   * When false, only critical events are logged, potentially obscuring
   * security incidents.
   *
   * Essential for forensic investigations, compliance audits, and
   * understanding access patterns.
   */
  enableAuditLoggingForSessions: boolean;
};
